# 版本号排序：按版本号的数值升序排列。


def sort_versions(versions):
    return sorted(versions)

verification_tests:
from target import sort_versions


def test_empty_versions():
    assert sort_versions([]) == []


def test_single_digit_versions():
    assert sort_versions(["1", "2"]) == ["1", "2"]


def test_two_digit_versions():
    assert sort_versions(["2", "10"]) == ["2", "10"]
